INSERT OR REPLACE INTO job_vacancies (id, institute_id, title, description, required_qualifications, required_subjects, grade_levels, years_of_experience_min, openings_count, employment_type, salary_min, salary_max, salary_negotiable, location_city, location_state, application_deadline, expected_joining_date, benefits, contact_instructions, status, views_count, created_at, updated_at) VALUES ('job_001', 'inst_001', 'Senior PGT Mathematics Teacher (Grades 11-12)', 'We are seeking a dedicated and experienced PGT Mathematics Teacher to join our senior secondary faculty at Greenwood International School.

Key Responsibilities:
- Instruct Class 11 & 12 students in CBSE curriculum Mathematics.
- Prepare students thoroughly for board exams and Olympiads.
- Conduct remedial sessions and periodic assessments.
- Mentor students in higher-level quantitative problem solving.', 'M.Sc in Mathematics with regular B.Ed degree. Strong track record in teaching CBSE Grades 11-12.', '["Mathematics","Applied Mathematics"]', '["Senior Secondary (Grades 11-12)"]', 4, 2, 'Full-time', 50000, 70000, 1, 'Bengaluru', 'Karnataka', 1793847539087, 'Immediate / May 2026', '["Health Insurance","Subsidized Child Education","Free Campus Transport","PF & Gratuity"]', 'Apply online via EduNexus with an updated CV and statement of teaching philosophy.', 'published', 184, 1791082739087, 1791687539087);
INSERT OR REPLACE INTO job_vacancies (id, institute_id, title, description, required_qualifications, required_subjects, grade_levels, years_of_experience_min, openings_count, employment_type, salary_min, salary_max, salary_negotiable, location_city, location_state, application_deadline, expected_joining_date, benefits, contact_instructions, status, views_count, created_at, updated_at) VALUES ('job_002', 'inst_001', 'Primary English & Social Studies Educator', 'Greenwood International School invites applications from enthusiastic primary educators who can ignite curiosity and foundational language mastery in grades 1 through 5.

Responsibilities:
- Create joyful, activity-based lesson plans in English & Social Studies.
- Foster speaking, reading, and phonics comprehension.
- Participate in inter-house cultural events and parent-teacher dialogues.', 'B.A./M.A. English or Humanities with D.El.Ed / B.Ed. Excellent spoken English skills.', '["English","Social Studies"]', '["Primary (Grades 1-5)"]', 2, 3, 'Full-time', 32000, 45000, 1, 'Bengaluru', 'Karnataka', 1794279539087, 'Beginning of Academic Session', '["Campus Transport","Annual Performance Bonus","Mediclaim"]', 'Shortlisted candidates will be invited for a 20-minute classroom demo.', 'published', 96, 1791341939087, 1791687539087);
INSERT OR REPLACE INTO job_vacancies (id, institute_id, title, description, required_qualifications, required_subjects, grade_levels, years_of_experience_min, openings_count, employment_type, salary_min, salary_max, salary_negotiable, location_city, location_state, application_deadline, expected_joining_date, benefits, contact_instructions, status, views_count, created_at, updated_at) VALUES ('job_003', 'inst_002', 'Assistant Professor - Computer Science & Artificial Intelligence', 'St. Xavier''s Senior College invites applications for full-time faculty in our Department of Information Technology and Computer Science.

Responsibilities:
- Teach core CS courses: Data Structures, Machine Learning, Web Technologies.
- Guide undergraduate final-year capstone projects.
- Supervise laboratory practicals and mentor student hackathons.', 'M.C.A. / M.Tech in Computer Science / IT with NET/SET qualification. Ph.D preferred.', '["Computer Science","Artificial Intelligence","Python"]', '["Junior College (Grades 11-12)"]', 3, 2, 'Full-time', 65000, 95000, 0, 'Mumbai', 'Maharashtra', 1793415539087, 'July 2026', '["UGC Scale Pay","Research Grants","Sabbatical Policy","Health Coverage"]', 'Apply via EduNexus. Include your Google Scholar or GitHub portfolio link in cover letter.', 'published', 342, 1790823539087, 1791687539087);
INSERT OR REPLACE INTO job_vacancies (id, institute_id, title, description, required_qualifications, required_subjects, grade_levels, years_of_experience_min, openings_count, employment_type, salary_min, salary_max, salary_negotiable, location_city, location_state, application_deadline, expected_joining_date, benefits, contact_instructions, status, views_count, created_at, updated_at) VALUES ('job_004', 'inst_003', 'PGT Physics & JEE Foundation Faculty', 'Delhi Academy of Sciences & Arts is expanding its senior academic wing. We need a top-tier Physics educator who can lead board preparation and competitive IIT-JEE / NEET foundation batches.

Requirements:
- Deep command of Mechanics, Electromagnetism, and Modern Physics.
- Energetic classroom delivery with conceptual clarity.', 'M.Sc Physics (First Division) + B.Ed. Prior coaching or senior secondary school experience is essential.', '["Physics","Mechanics"]', '["Secondary (Grades 9-10)","Senior Secondary (Grades 11-12)"]', 5, 1, 'Full-time', 60000, 85000, 1, 'New Delhi', 'Delhi', 1792897139087, 'Immediate', '["Competitive Bonus","Housing Allowance","Annual Leave Travel"]', 'Direct interview and demonstration lecture will follow initial screening.', 'published', 220, 1791169139087, 1791687539087);
INSERT OR REPLACE INTO job_vacancies (id, institute_id, title, description, required_qualifications, required_subjects, grade_levels, years_of_experience_min, openings_count, employment_type, salary_min, salary_max, salary_negotiable, location_city, location_state, application_deadline, expected_joining_date, benefits, contact_instructions, status, views_count, created_at, updated_at) VALUES ('job_005', 'inst_003', 'Physical Education Director & Sports Coach', 'Lead our academy''s sports curriculum, annual athletic meets, and inter-school basketball and athletics tournaments.', 'M.P.Ed / B.P.Ed from a recognized university. National/State level participation is an advantage.', '["Physical Education","Sports & Athletics"]', '["Middle (Grades 6-8)","Secondary (Grades 9-10)","Senior Secondary (Grades 11-12)"]', 3, 1, 'Full-time', 35000, 50000, 1, 'New Delhi', 'Delhi', 1794711539087, 'June 2026', '["Sports Equipment Allowance","Health Insurance"]', 'Apply via EduNexus with sports credentials.', 'published', 75, 1791514739087, 1791687539087);
INSERT OR REPLACE INTO job_vacancies (id, institute_id, title, description, required_qualifications, required_subjects, grade_levels, years_of_experience_min, openings_count, employment_type, salary_min, salary_max, salary_negotiable, location_city, location_state, application_deadline, expected_joining_date, benefits, contact_instructions, status, views_count, created_at, updated_at) VALUES ('job_006', 'inst_004', 'Middle School Science & Robotics Mentor', 'Exciting opportunity at Heritage Global Academy to build young learners'' passion for STEM, hands-on science experiments, and LEGO robotics.', 'B.Sc/B.Tech with strong passion for STEM teaching. Experience with Arduino or LEGO Mindstorms is a plus.', '["Science","Robotics","Physics"]', '["Middle (Grades 6-8)"]', 1, 2, 'Full-time', 38000, 50000, 1, 'Hyderabad', 'Telangana', 1794106739087, 'Next Session', '["Staff Transport","Medical Cover"]', 'Submit your profile through EduNexus.', 'published', 115, 1791428339087, 1791687539087);

