INSERT OR REPLACE INTO bus_listings (id, institute_id, title, manufacturer, model, manufacturing_year, registration_year, registration_state, asking_price, is_negotiable, seating_capacity, fuel_type, odometer_kms, vehicle_condition, previous_owners, location_city, location_state, description, maintenance_info, primary_image_url, status, views_count, created_at, updated_at) VALUES ('bus_003', 'inst_003', 'Ashok Leyland Sunshine 50-Seater Eco-Friendly CNG Bus', 'Ashok Leyland', 'Sunshine CNG 50S', 2022, 2022, 'DL (Delhi)', 2100000, 1, 50, 'CNG', 29800, 'Excellent', 1, 'New Delhi', 'Delhi', 'Low-emission BS6 factory-fitted CNG school bus ideal for NCR regulations. Extra low entry step for junior students, tooth-guard padded seats, anti-skid vinyl flooring, full HD surveillance system with 30-day backup.', 'Complete OEM service logbook. Dual CNG cylinder hydrostatic testing verified. Transfer of ownership support provided directly by institution trust.', 'https://images.unsplash.com/photo-1557223562-6c77ef16210f?w=800&auto=format&fit=crop&q=80', 'published', 312, 1791255539087, 1791687539087);
INSERT OR REPLACE INTO bus_listings (id, institute_id, title, manufacturer, model, manufacturing_year, registration_year, registration_state, asking_price, is_negotiable, seating_capacity, fuel_type, odometer_kms, vehicle_condition, previous_owners, location_city, location_state, description, maintenance_info, primary_image_url, status, views_count, created_at, updated_at) VALUES ('bus_004', 'inst_001', 'Force Traveller 26-Seater Mini School Van', 'Force Motors', 'Traveller School 3700', 2020, 2020, 'KA (Karnataka)', 980000, 1, 26, 'Diesel', 51200, 'Good', 1, 'Bengaluru', 'Karnataka', 'Compact and maneuverable school bus ideal for inner-city colony routes. FM2.6 CR ED engine with smooth power steering. Clean seat covers and full safety railings.', 'Maintained under AMC. Battery replaced 3 months ago. Ready for immediate deployment.', 'https://images.unsplash.com/photo-1568605117036-5fe5e7bab0b7?w=800&auto=format&fit=crop&q=80', 'published', 145, 1791514739087, 1791687539087);

